import re
from decimal import Context, Decimal, ROUND_DOWN

MAX_AMOUNT = Decimal("1000000.00")
_CENT = Decimal("0.01")
_PLAIN_DECIMAL = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?", re.ASCII)

# Private context: the global decimal context is never read or modified.
_CTX = Context(prec=50, rounding=ROUND_DOWN, Emin=-999999999, Emax=999999999, traps=[])


def _to_decimal(value):
    if isinstance(value, bool):
        raise ValueError("booleans are not valid amounts")
    if isinstance(value, Decimal):
        return value
    if isinstance(value, int):
        return Decimal(value)
    if isinstance(value, str):
        if not _PLAIN_DECIMAL.fullmatch(value):
            raise ValueError("invalid amount string")
        return Decimal(value)
    raise ValueError("unsupported amount type")


def parse_amount(value):
    """Return a positive Decimal with exponent -2, or raise ValueError."""
    dec = _to_decimal(value)
    if not dec.is_finite():
        raise ValueError("amount must be finite")
    if dec <= 0:
        raise ValueError("amount must be positive")
    if dec > MAX_AMOUNT:
        raise ValueError("amount too large")
    cents = dec.quantize(_CENT, context=_CTX)
    if cents != dec:  # exact comparison: a nonzero sub-cent part is never rounded away
        raise ValueError("amount not representable in cents")
    return cents


def format_amount(value):
    return format(value, ".2f")
